# -*- coding: utf-8 -*-
from _lib import *
MM='Manuel des Monstres 5e (2014)'
I(2,'Dans D&D 5e, lequel de ces monstres n’a pas de tentacules ?','Umber hulk',['Aboleth','Flagelleur mental','Otyugh'],'L’umber hulk creuse la roche avec ses griffes et ses mandibules. L’aboleth, le flagelleur mental et l’otyugh ont des tentacules.',MM+', entrées correspondantes')
I(2,'Dans D&D 5e, lequel de ces effets n’est pas un rayon oculaire du tyrannœil ?','Boule de feu',['Charme','Paralysie','Désintégration'],'Les dix rayons du tyrannœil : charme, paralysie, peur, ralentissement, énervation, télékinésie, sommeil, pétrification, désintégration et mort. Pas de boule de feu.',MM+', entrée « Tyrannœil »')
I(3,'Dans D&D 5e, lequel de ces monstres n’est pas une aberration ?','Mimique',['Tyrannœil','Flagelleur mental','Aboleth'],'Le mimique est une monstruosité. Le tyrannœil, le flagelleur mental et l’aboleth sont des aberrations.',MM+', entrées correspondantes')
T(1,'Dans D&D 5e, le flagelleur mental dévore le ____ de ses victimes.','cerveau',['cœur','foie','sang'],'Son attaque « Extraction du cerveau » tue sa victime en lui dévorant le cerveau.',MM+', entrée « Flagelleur mental »')
T(2,'Dans D&D 5e, le grand œil central du tyrannœil crée un cône d’____.','antimagie',['obscurité','illusion','infravision'],'Le cône d’antimagie du tyrannœil supprime la magie dans sa zone.',MM+', entrée « Tyrannœil »')
T(3,'Dans D&D 5e, une colonie de flagelleurs mentaux est dirigée par un ____.','elder brain',['tyran de la mort','cloaker','aboleth'],'Au cœur de la colonie illithide, l’elder brain commande les flagelleurs mentaux.',MM+', entrée « Elder brain »')
M(3,'Dans D&D 5e, lesquels de ces monstres ont un FP supérieur à 10 ? (plusieurs bonnes réponses)',['Tyrannœil','Tyran de la mort','Elder brain'],['Aboleth','Flagelleur mental'],'FP : tyrannœil 13, tyran de la mort 14, elder brain 14 ; aboleth 10 et flagelleur mental 7 sont en dessous.',MM+', blocs de caractéristiques')
M(2,'Dans D&D 5e, lesquels de ces monstres sont des aberrations ? (plusieurs bonnes réponses)',['Tyrannœil','Aboleth','Dévoreur d’intellect'],['Mimique','Gargouille'],'Tyrannœil, aboleth et dévoreur d’intellect sont des aberrations ; mimique et gargouille ne le sont pas.',MM+', entrées correspondantes')
M(3,'Dans D&D 5e, lesquels de ces monstres ont un FP inférieur ou égal à 5 ? (plusieurs bonnes réponses)',['Umber hulk','Chuul','Gibbering mouther'],['Cloaker','Flagelleur mental'],'FP : umber hulk 5, chuul 4, gibbering mouther 2 ; cloaker 8 et flagelleur mental 7 sont plus dangereux.',MM+', blocs de caractéristiques')
O(3,'Classe ces aberrations par FP croissant.',['Gibbering mouther','Chuul','Flagelleur mental','Aboleth','Tyrannœil'],'FP : gibbering mouther 2, chuul 4, flagelleur mental 7, aboleth 10, tyrannœil 13.',MM+', blocs de caractéristiques')
O(3,'Classe ces monstres par FP croissant.',['Dévoreur d’intellect','Umber hulk','Cloaker','Tyran de la mort'],'FP : dévoreur d’intellect 2, umber hulk 5, cloaker 8, tyran de la mort 14.',MM+', blocs de caractéristiques')
A(1,'Associe chaque aberration à son apparence.',[('Tyrannœil','Sphère aux pédoncules oculaires'),('Flagelleur mental','Tentacules autour de la bouche'),('Cloaker','Grande cape noire'),('Dévoreur d’intellect','Cerveau à pattes')],'Chaque aberration a une silhouette distinctive.',MM+', entrées correspondantes')
A(2,'Associe chaque monstre à sa capacité caractéristique.',[('Tyrannœil','Cône d’antimagie'),('Flagelleur mental','Explosion mentale'),('Aboleth','Asservissement'),('Umber hulk','Regard confusant')],'Antimagie (tyrannœil), explosion mentale (flagelleur), asservissement (aboleth), regard confusant (umber hulk).',MM+', entrées correspondantes')
W(1,['Je suis une sphère flottante.','J’ai un grand œil central et de nombreux pédoncules.','Mon regard central annule la magie.'],'Tyrannœil',['Flagelleur mental','Cloaker','Gibbering mouther'],'Le tyrannœil (beholder) est un tyran paranoïaque aux dix rayons oculaires.',MM+', entrée « Tyrannœil »')
W(2,['Je viens de l’Outreterre.','Ma tête ressemble à une pieuvre.','Je domine par la pensée et je me nourris de cerveaux.'],'Flagelleur mental',['Aboleth','Chuul','Otyugh'],'Le flagelleur mental (illithid) règne par la télépathie et l’extraction de cerveau.',MM+', entrée « Flagelleur mental »')
W(3,['Je ressemble à un cerveau qui marche sur quatre pattes.','Je dévore l’esprit de ma proie.','Une fois son cerveau détruit, je prends possession de son corps.'],'Dévoreur d’intellect',['Gibbering mouther','Otyugh','Cloaker'],'Le dévoreur d’intellect détruit l’esprit puis s’empare du corps de sa victime.',MM+', entrée « Dévoreur d’intellect »')
save('aberrations-dnd','abe')
